using System;using System.IO;using UnityEngine;using FlyEditor.Flight;using FlyEditor.Editor;
public static class CraneOppositeWings {public static void Run(){string root=Environment.GetEnvironmentVariable("FLYEDITOR_CRANE_FINISH");var s=PaperSheet.Replay(JsonUtility.FromJson<ResearchSave>(File.ReadAllText(Path.Combine(root,"angles-root-3.8.json"))).paperFolds);
foreach(float hinge in new[]{4.25f,4.5f,4.75f,5f,5.25f,5.5f})foreach(bool order in new[]{true,false})foreach(float sign in new[]{90f,-90f}){var a=order?new Vector2(11,0):new Vector2(0,11);var b=order?new Vector2(0,11):new Vector2(11,0);bool first=WingSearch.Wing(s,a,hinge,out var one,sign);Debug.Log("[OppositeWings] hinge="+hinge+" order="+order+" sign="+sign+" first="+first);if(!first)continue;bool second=WingSearch.Wing(one,b,hinge,out var two,-sign);Debug.Log("[OppositeWings] second="+second);if(!second)continue;ReverseDirectionVerification.Geometry(two.Faces);PetalFoldingVerification.Replay(two);CraneAngles.Capture(two,root,"opposite-wings");return;}throw new Exception("No opposite wings");}}
